/// <summary>
/// Extension class for the UnitOfMeasureConversion form in order to add the AVARUM specific fields and logic.
/// </summary>
[ExtensionOf(formStr(UnitOfMeasureConversion))]
final class AVARUMUnitOfMeasureConversionFrm_Extension
{
}

Method.Source:
/// <summary>
/// Overrides the run method to set the correct tab page based on the caller record type.
/// </summary>
public void run()
{
    const int ConversionAllTabPageNumber = 1;
    const int ConversionStandardTabPageNumber = 2;
    const int ConversionIntraclassTabPageNumber = 3;

    next run();

    if (this.args() && this.args().record())
    {
        Common callerRecord = this.args().record();

        if (callerRecord is EcoResProduct)
        {
            tocTab.tab(ConversionAllTabPageNumber);
        }

        if (callerRecord is UnitOfMeasure)
        {
            tocTab.tab(ConversionStandardTabPageNumber);
        }

        if (callerRecord is WHSPhysDimUOM)
        {
            tocTab.tab(ConversionIntraclassTabPageNumber);
        }
    }
    else
    {
        tocTab.tab(ConversionStandardTabPageNumber);

        FormTabPageControl allTab = this.control(this.controlId(FormControlstr(UnitOfMeasureConversion, TOCPageConversionAll))) as FormTabPageControl;

        if (allTab)
        {
            allTab.visible(false);
        }
    }
}
